public class SwordSoaringArmatures {
    public static Armatures.ArmatureAccessor<WanArmature> WAN_ARMATURE = Armatures.ArmatureAccessor.create((String)"sword_soaring", (String)"entity/wan", WanArmature::new);
    public static Armatures.ArmatureAccessor<BabylonArmature> BABYLON_ARMATURE = Armatures.ArmatureAccessor.create((String)"sword_soaring", (String)"entity/babylon", BabylonArmature::new);
    public static Armatures.ArmatureAccessor<FlySwordArmature> FLY_SWORD_ARMATURE = Armatures.ArmatureAccessor.create((String)"sword_soaring", (String)"entity/fly_sword", FlySwordArmature::new);
    public static Armatures.ArmatureAccessor<ScreenSwordArmature> SCREEN_SWORD_ARMATURE = Armatures.ArmatureAccessor.create((String)"sword_soaring", (String)"entity/screen_sword", ScreenSwordArmature::new);
    public static Armatures.ArmatureAccessor<VatanseverArmature> VATANSEVER_ARMATURE = Armatures.ArmatureAccessor.create((String)"sword_soaring", (String)"entity/vatansever", VatanseverArmature::new);
    public static Armatures.ArmatureAccessor<VatanseverStormArmature> VATANSEVER_STORM_ARMATURE = Armatures.ArmatureAccessor.create((String)"sword_soaring", (String)"entity/vatansever_swordgroup", VatanseverStormArmature::new);

    public static void registerArmatures() {
        Armatures.registerEntityTypeArmature((EntityType)((EntityType)SwordSoaringEntities.WAN_ENTITY.get()), WAN_ARMATURE);
        Armatures.registerEntityTypeArmature((EntityType)((EntityType)SwordSoaringEntities.BABYLON.get()), BABYLON_ARMATURE);
